import neo4j from 'neo4j-driver';

const driver = neo4j.driver('bolt://localhost:7687', neo4j.auth.basic('neo4j','password'));
export const session = driver.session();

export async function addRelation(a:string,b:string,type:string,weight:number){
 await session.run(
  'MERGE (x:Entity {id:$a}) MERGE (y:Entity {id:$b}) MERGE (x)-[r:'+type+']->(y) SET r.weight=$w',
  {a,b,w:weight}
 );
}

