Player Action Pipeline (FINAL FORM).code:
import { validate } from '../arelogic/watchdog.engine';
import { mapActionToE } from '../arelogic/event.mapper';
import { updateHeuristics } from '../arelogic/heuristic.engine';
import { addRelation } from '../db/neo4j';

export async function handleAction(action:any){
 if(!validate(action)) return null;

 const E = mapActionToE(action.type);
 await updateHeuristics(E);

 await addRelation(action.playerId, action.targetId || 'world', action.type, 1);

 return action;
}
